export interface CatalogCao {
  name: string;
  fnvUrl: string;
  /** true if we have full salary data in caos2026 */
  calculable?: boolean;
  /** id of the matching caos2026 record (only when calculable) */
  caoId?: string;
  /**
   * true = structurally not calculable in our salary-table model, so it will
   * never be `calculable`. The canonical case is uitzend (NBBU/ABU): an
   * uitzendkracht is paid the inlenersbeloning — the wage of the CAO at the
   * hiring company — so there is no own salary scale to model.
   */
  notApplicable?: boolean;
  /** Short reason, shown to users / skipped by the extraction pipeline. */
  notApplicableReason?: string;
}

export interface CatalogSector {
  sector: string;
  caos: CatalogCao[];
}

